SELECT STATUS status, PROD_ID prodId, PROD_NAME prodName, PROD_INS_ID prodInsId, PROD_BRAND prodBrand, PROD_STAGE prodStage, APPROVER_ID approverId, APPROVER_NAME approverName, DESIGNER_ID designerId, DESIGNER_NAME designerName, MANAGER_ID managerId, MANAGER_NAME managerName, LIAISON_NAME liaisonName, LIAISON_TEL liaisonTel, LIAISON_MOBILE liaisonMobile, LIAISON_EMAIL liaisonEmail, RAISE_TYPE raiseType, PROFIT_TYPE prodtype, IS_FHXGCP isFhxgcp, TERMTYPE termtype, EXC_FIN_SECTOR excFinSector, INVEST_ARAE investArae, INVEST_COUNTRY investCountry, FINAN_SER_MODEL finanSerModel, OPERATE_MODE operateMode, IS_SHORT_TERM isShortTerm, SHORT_TERM shortTerm, IS_FREE_REDEM isFreeRedem, CASH_MANA_CATE cashManaCate, CMMODE cmmode, PMMODE pmmode, MNAME mname, PRICED_MODE pricedMode, IVSTORIENTATION ivstorientation, CONT_MODE contMode, COOPERATION_NAME cooperationName, INV_TYPE_RAT invTypeRat, YIELD yield, RISK_TYPE riskType, SALE_AREA saleArea, RAISE_CCY raiseCcy, CASH_PRIN_CCY cashPrinCcy, CASH_PROF_CCY cashProfCcy, SALE_AMT_STR saleAmtStr, RAISE_AMT_PLAN raiseAmtPlan, RAISE_PSTRDATE raisePstrdate, RAISE_PENDDATE raisePenddate, INVEST_PRIN_DATE investPrinDate, INVEST_PROF_DATE investProfDate, SALE_FEE_RATE saleFeeRate, INVEST_FEE_RATE investFeeRate, IN_DEP_NAME inDepName, IN_DEP_CODE inDepCode, OUT_DEP_CTRY outDepCtry, OUT_DEP_NAME outDepName, TRU_FEE_RATE truFeeRate, RISK_LEVEL riskLevel, TERM_RIGHT_FLAG termRightFlag, CUS_REDEEM_FLAG cusRedeemFlag, CREDIT_FLAG creditFlag, CREDIT_TYPE creditType, CREDIT_MODE creditMode, RAISE_VDATE raiseVdate, RAISE_ENDDATE raiseEnddate, VDATE vdate, MDATE mdate, MANAGE_TYPE manageType, IS_CONSTRACTE isConstracte, YIELD_HIGH yieldHigh, YIELD_LOW yieldLow, YIELD_REMARK yieldRemark, OPEN_MODE openMode, OPEN_CIRCLE openCircle, OPEN_CIRCLE_DAYS openCircleDays, RULE_COMMENT ruleComment, FIRST_OPEN_DAY firstOpenDay, HOLIDAY_ON_FLAG holidayOnFlag, AVG_OPEN_COUNT avgOpenCount, OPEN_BUSS openBuss, OPEN_BUSS_REMARK openBussRemark, BUSI_ACCT_NO busiAcctNo, ACCT_NAME acctName, FIDUCIARY_DUTY fiduciaryDuty, CUSTOMER_TYPE customerType, IS_TRANSFER isTransfer, IS_FULLY_COMPLIANT isFullyCompliant, IS_YLLCCP isYllccp, TRANSFER_TYPE transferType, REMARK remark, CREATE_USER createUser, CREATE_TIME createTime, UPDATE_USER updateUser, UPDATE_TIME updateTime, SVR_DATA_SOURCES dataSource, '' dataUuid, '' orgData, '' errMsg FROM CHB_PRD_BASEINFO a
not EXISTS ( SELECT 1 from chb_prd_baseinfo_errordata b where b.PROD_ID=a.PROD_ID and b.STATUS in('A','E') )
#{prodId,jdbcType=VARCHAR}
DATE_FORMAT(RAISE_VDATE,'%Y-%m-%d') >= #{raiseVdate,jdbcType=VARCHAR}
and DATE_FORMAT(RAISE_VDATE,'%Y-%m-%d') <= #{raiseEnddate,jdbcType=VARCHAR}
DATE_FORMAT(VDATE,'%Y-%m-%d') >= #{vdate,jdbcType=VARCHAR}
and DATE_FORMAT(VDATE,'%Y-%m-%d') <= #{mdate,jdbcType=VARCHAR}
#{status,jdbcType=VARCHAR}
union all SELECT 'A' as status, PROD_ID prodId, PROD_NAME prodName, '' prodInsId, '' prodBrand, '' prodStage, '' approverId, '' approverName, '' designerId, '' designerName, '' managerId, '' managerName, '' liaisonName, '' liaisonTel, '' liaisonMobile, '' liaisonEmail, '' raiseType, '' prodtype, '' isFhxgcp, '' termtype, '' excFinSector, '' investArae, '' investCountry, '' finanSerModel, '' operateMode, '' isShortTerm, '' shortTerm, '' isFreeRedem, '' cashManaCate, '' cmmode, '' pmmode, '' mname, '' pricedMode, '' ivstorientation, '' contMode, '' cooperationName, '' invTypeRat, '' yield, '' riskType, '' saleArea, '' raiseCcy, '' cashPrinCcy, '' cashProfCcy, '' saleAmtStr, '' raiseAmtPlan, '' raisePstrdate, '' raisePenddate, '' investPrinDate, '' investProfDate, '' saleFeeRate, '' investFeeRate, '' inDepName, '' inDepCode, '' outDepCtry, '' outDepName, '' truFeeRate, '' riskLevel, '' termRightFlag, '' cusRedeemFlag, '' creditFlag, '' creditType, '' creditMode, RAISE_VDATE raiseVdate, '' raiseEnddate, VDATE vdate, '' mdate, '' manageType, '' isConstracte, '' yieldHigh, '' yieldLow, '' yieldRemark, '' openMode, '' openCircle, '' openCircleDays, '' ruleComment, '' firstOpenDay, '' holidayOnFlag, '' avgOpenCount, '' openBuss, '' openBussRemark, '' busiAcctNo, '' acctName, '' fiduciaryDuty, '' customerType, '' isTransfer, '' isFullyCompliant, '' isYllccp, '' transferType, '' remark, CREATE_USER createUser, CREATE_TIME createTime, UPDATE_USER updateUser, UPDATE_TIME updateTime, 'DB' dataSource, DATAUUID dataUuid, ORG_DATA orgData, ERR_MSG errMsg FROM chb_prd_baseinfo_errordata c
c.STATUS in('A','E')
#{prodId,jdbcType=VARCHAR}
DATE_FORMAT(RAISE_VDATE,'%Y-%m-%d') >= #{raiseVdate,jdbcType=VARCHAR}
and DATE_FORMAT(RAISE_VDATE,'%Y-%m-%d') <= #{raiseEnddate,jdbcType=VARCHAR}
DATE_FORMAT(VDATE,'%Y-%m-%d') >= #{vdate,jdbcType=VARCHAR}
and DATE_FORMAT(VDATE,'%Y-%m-%d') <= #{mdate,jdbcType=VARCHAR}
and 1 = 2

	SELECT count(1) from (
SELECT 1 from REP_CASH_YIELD a
	where a.STATUS in('A','E')
	and not EXISTS (
	 SELECT 1 from 	REP_CASH_YIELD_ERRORDATA b
			WHERE b.PROD_ID=a.BUSI_ID
				and b.CASH_TYPE_2=a.CASH_TYPE2
			and b.START_DATE=a.START_DATE
			and b.STATUS in('A','E')
	) and

	a.BUSI_ID = #{item.busiId,jdbcType=VARCHAR}
	and a.START_DATE = #{item.startDate,jdbcType=DATE}
	and a.CASH_TYPE2 = #{item.cashType2,jdbcType=VARCHAR}


	union all
	SELECT 1 from rep_cash_yield_errordata c
	where c.STATUS in('A','E')
and

	c.PROD_ID = #{item.busiId,jdbcType=VARCHAR}
	and c.START_DATE = #{item.startDate,jdbcType=DATE}
	and c.CASH_TYPE_2 = #{item.cashType2,jdbcType=VARCHAR}


)tmp

